CREATE TEMP TABLE aug3_test_result ON COMMIT DROP AS SELECT n tests_passed,v positive_summary,population_top3000_202608_202609_v1.population_recovery_manifest_v1()prospective_manifest,(SELECT coalesce(sum(pg_total_relation_size(oid)),0)FROM pg_class WHERE relnamespace='population_top3000_202608_202609_v1'::regnamespace AND relname IN('ctx06_aug03_vote_v5','ctx06_aug03_summary_v5'))positive_new_tables_bytes, population_top3000_202608_202609_v1.ctx06_aug03_bundle_v5()bundle_sha256,(SELECT jsonb_object_agg(proname,encode(sha256(convert_to(pg_get_functiondef(oid),'UTF8')),'hex'))FROM pg_proc WHERE pronamespace='population_top3000_202608_202609_v1'::regnamespace AND proname LIKE'ctx06_aug03_%_v5')function_hashes;
END$test$;
$tests$;SELECT to_jsonb(t)INTO proof FROM aug3_test_result t;RAISE EXCEPTION'ROLLBACK_SUCCESS';EXCEPTION WHEN raise_exception THEN IF SQLERRM IS DISTINCT FROM'ROLLBACK_SUCCESS'THEN RAISE;END IF;END;INSERT INTO aug3_capture VALUES(proof);END$outer$;
DO $$DECLARE after_value jsonb;BEGIN
SELECT jsonb_build_object('acquisition',(SELECT to_jsonb(a)FROM population_top3000_202608_202609_v1.acquisition_control a WHERE singleton),'pipeline',(SELECT to_jsonb(p)FROM population_top3000_202608_202609_v1.pipeline_control p WHERE singleton),'tasks',(SELECT jsonb_build_array(count(*),encode(sha256(convert_to(string_agg(tableoid::text||':'||ctid::text||':'||xmin::text,E'\n'ORDER BY tableoid,ctid),'UTF8')),'hex'))FROM population_top3000_202608_202609_v1.pipeline_task),'attempts',(SELECT jsonb_build_array(count(*),encode(sha256(convert_to(string_agg(tableoid::text||':'||ctid::text||':'||xmin::text,E'\n'ORDER BY tableoid,ctid),'UTF8')),'hex'))FROM population_top3000_202608_202609_v1.pipeline_attempt),'commits',(SELECT jsonb_build_array(count(*),encode(sha256(convert_to(string_agg(tableoid::text||':'||ctid::text||':'||xmin::text,E'\n'ORDER BY tableoid,ctid),'UTF8')),'hex'))FROM population_top3000_202608_202609_v1.pipeline_commit),'votes',(SELECT encode(sha256(convert_to(string_agg(record_sha256,E'\n'ORDER BY run_key,company_ordinal,session_date),'UTF8')),'hex')FROM population_top3000_202608_202609_v1.ctx06_observed_vote_v4),'sessions',(SELECT encode(sha256(convert_to(string_agg(record_sha256,E'\n'ORDER BY run_key,session_date),'UTF8')),'hex')FROM population_top3000_202608_202609_v1.ctx06_observed_session_v4),'recovery',(SELECT details FROM population_top3000_202608_202609_v1.pipeline_event WHERE event='RECOVERY_DELEGATION_QUALIFIED_V1'ORDER BY event_id DESC LIMIT 1),'cron',(SELECT jsonb_agg(to_jsonb(j)ORDER BY jobid)FROM cron.job j WHERE jobid IN(596,597)),'old8',(SELECT jsonb_object_agg(proname,encode(sha256(convert_to(pg_get_functiondef(oid),'UTF8')),'hex'))FROM pg_proc WHERE pronamespace='population_top3000_202608_202609_v1'::regnamespace AND proname LIKE'practical_delivery_%_v1'))INTO after_value;
IF after_value IS DISTINCT FROM(SELECT baseline FROM aug3_before)OR to_regclass('population_top3000_202608_202609_v1.ctx06_aug03_vote_v5')IS NOT NULL THEN RAISE EXCEPTION'FULL_PROTECTED_RESTORATION_FAILED';END IF;END$$;
DO $$DECLARE growth bigint;BEGIN SELECT greatest(0,(SELECT coalesce(sum(pg_total_relation_size(oid)),0)FROM pg_class WHERE relnamespace='population_top3000_202608_202609_v1'::regnamespace AND relkind IN('r','m'))-mission_relation_bytes)INTO growth FROM aug3_before;IF 33554432+growth+(SELECT(proof->>'positive_new_tables_bytes')::bigint FROM aug3_capture)>67108864 THEN RAISE EXCEPTION'ACTUAL_WHOLE_PG_RELATION_GROWTH_64MIB';END IF;UPDATE aug3_capture SET proof=proof||jsonb_build_object('mission_relation_before',(SELECT mission_relation_bytes FROM aug3_before),'mission_relation_after_rollback',(SELECT coalesce(sum(pg_total_relation_size(oid)),0)FROM pg_class WHERE relnamespace='population_top3000_202608_202609_v1'::regnamespace AND relkind IN('r','m')),'persistent_relation_growth_after_rollback',growth,'conservative_growth_charge',33554432+growth+(proof->>'positive_new_tables_bytes')::bigint,'voluntary_conservative_budget_reserve',33554432,'reserve_basis','VOLUNTARY_RESERVE_NOT_MEASURED_HISTORICAL_GROWTH_OR_PROVED_UPPER_BOUND','maximum_additional_relation_bytes',67108864,'first_two_failed_test_growth_individually_unmeasured',true);END$$;
SELECT proof||jsonb_build_object('full_protected_restoration',true,'new_objects_absent',true,'production_effects',false)actual_test_result FROM aug3_capture;
ROLLBACK;
